+      border-radius: 28px;
+      box-shadow: var(--shadow);
+    }
+
+    .support-intro {
+      padding: 44px;
+      color: #ffffff;
+      background:
+        linear-gradient(160deg, rgba(15, 23, 42, 0.3), transparent),
+        linear-gradient(135deg, #2563eb, #0f172a);
+    }
+
+    .eyebrow {
+      margin: 0 0 18px;
+      font-size: 0.78rem;
+      font-weight: 700;
+      letter-spacing: 0.12em;
+      text-transform: uppercase;
+      opacity: 0.78;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2rem, 5vw, 3.25rem);
+      line-height: 1;
+      letter-spacing: -0.055em;
+    }
+
+    .support-intro p:last-child {
+      margin: 22px 0 0;
+      color: rgba(255, 255, 255, 0.78);
+      line-height: 1.7;
+    }
+
+    .contact-form {
+      padding: 44px;
+    }
+
+    .form-field {
+      margin-bottom: 22px;
+    }
+
+    label {
+      display: block;
+      margin-bottom: 8px;
+      font-size: 0.92rem;
+      font-weight: 700;
+      color: #26334d;
+    }
+
+    input {
+      width: 100%;
+      min-height: 52px;
+      padding: 0 16px;
+      color: var(--text);
+      background: var(--surface-muted);
+      border: 1px solid var(--border);
+      border-radius: 14px;
+      font: inherit;
+      transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
+    }
+
+    input::placeholder {
+      color: #9aa7b8;
+    }
+
+    input:focus {
+      outline: none;
+      background: #ffffff;
+      border-color: var(--primary);
+      box-shadow: 0 0 0 4px var(--ring);
+    }
+
+    .helper-text {
+      margin: 8px 0 0;
+      color: var(--muted);
+      font-size: 0.88rem;
+      line-height: 1.45;
+    }
+
+    .submit-button {
+      width: 100%;
+      min-height: 54px;
+      border: 0;
+      border-radius: 16px;
+      color: #ffffff;
+      background: linear-gradient(135deg, var(--primary), var(--primary-dark));
+      box-shadow: 0 14px 26px rgba(37, 99, 235, 0.22);
+      cursor: pointer;
+      font: inherit;
+      font-weight: 800;
+      transition: transform 160ms ease, box-shadow 160ms ease;
+    }
+
+    .submit-button:hover {
+      transform: translateY(-1px);
+      box-shadow: 0 18px 34px rgba(37, 99, 235, 0.28);
+    }
+
+    .submit-button:focus-visible {
+      outline: 4px solid var(--ring);
+      outline-offset: 3px;
+    }
+
+    @media (max-width: 720px) {
+      .support-card {
+        grid-template-columns: 1fr;
+      }
+
+      .support-intro,
+      .contact-form {
+        padding: 32px 24px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main id="app"></main>
+
+  <script>
+    const Field = ({ id, label, type = "text", placeholder, required = false, helperText, autocomplete, inputmode, pattern }) => `
+      <div class="form-field">
+        <label for="${id}">${label}</label>
+        <input
+          id="${id}"
+          name="${id}"
+          type="${type}"
+          placeholder="${placeholder}"
+          autocomplete="${autocomplete}"
+          ${inputmode ? `inputmode="${inputmode}"` : ""}
+          ${pattern ? `pattern="${pattern}"` : ""}
+          ${helperText ? `aria-describedby="${id}-helper"` : ""}
+          ${required ? "required" : ""}
+        >
+        ${helperText ? `<p class="helper-text" id="${id}-helper">${helperText}</p>` : ""}
+      </div>
+    `;
+
+    const SupportIntro = () => `
+      <section class="support-intro" aria-labelledby="support-title">
+        <p class="eyebrow">Support</p>
+        <h1 id="support-title">How can we help?</h1>
+        <p>Send our team a few details and we will route your request to the right specialist.</p>
+      </section>
+    `;
+
+    const ContactForm = () => `
+      <form class="contact-form" action="#" method="post" novalidate>
+        ${Field({
+          id: "full-name",
+          label: "Full name",
+          placeholder: "Alex Morgan",
+          autocomplete: "name",
+          required: true
+        })}
+        ${Field({
+          id: "email-address",
+          label: "Email address",
+          type: "email",
+          placeholder: "alex@example.com",
+          autocomplete: "email",
+          required: true
+        })}
+        ${Field({
+          id: "phone-number",
+          label: "Phone number",
+          type: "tel",
+          placeholder: "(555) 123-4567",
+          autocomplete: "tel",
+          inputmode: "tel",
+          pattern: "[0-9()+\\-\\s.]*",
+          helperText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567."
+        })}
+        <button class="submit-button" type="submit">Contact support</button>
+      </form>
+    `;
+
+    const App = () => `
+      <div class="page-shell">
+        <article class="support-card">
+          ${SupportIntro()}
+          ${ContactForm()}
+        </article>
+      </div>
+    `;
+
+    document.getElementById("app").innerHTML = App();
+  </script>
+</body>
+</html>
*** End Patch
