node - <<'NODE'
const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');
const staticHtml = html.split('<script>', 1)[0];
const inputs = [...staticHtml.matchAll(/<input\b[^>]*>/g)].map(match => match[0]);
const inputTag = (id) => inputs.find(tag => tag.includes(`id="${id}"`)) || '';
const checks = {
  static_form_fields: (staticHtml.match(/<div class="form-field">/g) || []).length === 3,
  full_name_required: /required\b/.test(inputTag('full-name')),
  email_required: /required\b/.test(inputTag('email-address')),
  phone_optional: !/required\b/.test(inputTag('phone-number')),
  phone_helper: /id="phone-number-helper"/.test(staticHtml) && /format like/.test(staticHtml),
  submit_button: /type="submit"/.test(staticHtml),
};
for (const [key, value] of Object.entries(checks)) console.log(`${key}: ${value}`);
process.exit(Object.values(checks).every(Boolean) ? 0 : 1);
